// Generated by scripts/blockart_glyphs.py; do not edit.
// Glyphs: Misaki Gothic 2nd 8x8 (c) Num Kadoma, https://littlelimit.net/misaki.htm (free licence).
pragma solidity ^0.8.30;

/// @notice 8x8 bitmaps for the characters the scenes draw (row-major, MSB = top-left).
library Glyphs {
    uint256 internal constant COUNT = 38;
    uint256 internal constant WORDS = 15;
    /// @dev 0:電 1:脳 2:暗 3:号 4:鍵 5:署 6:名 7:検 8:証 9:連 10:鎖 11:量 12:子 13:未 14:来 15:都 16:市 17:零 18:壱 19:夜 20:光 21:速 22:記 23:録 24:ベ 25:ー 26:ス 27:ブ 28:ロ 29:ッ 30:ク 31:・ 32:ガ 33:駅 34:次 35:は 36:の 37:ー|
    bytes internal constant TABLE =
        hex"";
    /// @dev Sign word w for vertical signs, 4 bytes each: length, then up to 3 glyph indices.
    bytes internal constant VERTICAL_WORDS =
        hex"020001000202030001040000020506000207080002090a00020b0c00020d0e00020f100001110000011200000213100002141500021617000318251a";
    /// @dev ベース・ブロック
    bytes internal constant BASE_BLOCK = hex"18191a1f1b1c1d1e";
    /// @dev ガス
    bytes internal constant GAS = hex"201a";
    /// @dev 駅
    bytes internal constant STATION = hex"21";
    /// @dev 次は
    bytes internal constant NEXT = hex"2223";
    /// @dev 次の駅
    bytes internal constant NEXT_STATION = hex"222421";
    /// @dev ベース written vertically (torii plaque).
    bytes internal constant BASE_VERTICAL = hex"18251a";

    function bits(bytes memory table, uint256 g) internal pure returns (uint256 v) {
        assembly ("memory-safe") {
            v := shr(192, mload(add(add(table, 32), mul(g, 8))))
        }
    }

    /// @dev Glyph indices of sign word w (0..14) in vertical form: (length, packed indices).
    function word(uint256 w) internal pure returns (uint256 len, uint256 ix) {
        bytes memory t = VERTICAL_WORDS;
        len = uint8(t[4 * w]);
        ix = uint256(uint8(t[4 * w + 1])) | uint256(uint8(t[4 * w + 2])) << 8 | uint256(uint8(t[4 * w + 3])) << 16;
    }
}

